import type { Project } from '../types/schema.ts';
import { generateMultiServiceOpenApi } from './openapiSynth.ts';

/**
 * Generates an end-to-end, strongly-typed TypeScript Client SDK
 * derived directly from the OpenAPI 3.1 specification.
 */
export function generateTypeScriptSdk(project: Project): string {
  const spec = generateMultiServiceOpenApi(project);

  return `/**
 * ==============================================================================
 * Generated TypeScript Client SDK
 * System: ${project.name} (v${project.version})
 * Generated by VoiceArchitect SDK Synthesizer
 * ==============================================================================
 */

export interface SdkConfig {
  baseUrl?: string;
  authToken?: string;
  timeoutMs?: number;
}

export interface ApiError {
  error: string;
  message: string;
  statusCode: number;
  timestamp: string;
}

export interface LoginRequest {
  username: string;
  password?: string;
}

export interface LoginResponse {
  token: string;
  expiresIn: number;
  tokenType: string;
}

export interface ProductItem {
  id: string;
  sku: string;
  name: string;
  price: number;
  inStock: boolean;
}

export interface CreateOrderRequest {
  items: Array<{ productId: string; quantity: number }>;
  shippingAddress: string;
  paymentMethodId: string;
}

export interface OrderRecord {
  orderId: string;
  status: 'PENDING' | 'PAID' | 'PROCESSING' | 'FAILED';
  totalAmount: number;
  createdAt: string;
}

export class CommercePlatformClient {
  private baseUrl: string;
  private authToken?: string;
  private timeoutMs: number;

  constructor(config: SdkConfig = {}) {
    this.baseUrl = config.baseUrl || 'https://api.commerceplatform.local/v1';
    this.authToken = config.authToken;
    this.timeoutMs = config.timeoutMs || 8000;
  }

  setAuthToken(token: string): void {
    this.authToken = token;
  }

  private async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...(this.authToken ? { Authorization: \`Bearer \${this.authToken}\` } : {}),
      ...((options.headers as Record<string, string>) || {}),
    };

    try {
      const response = await fetch(\`\${this.baseUrl}\${endpoint}\`, {
        ...options,
        headers,
        signal: controller.signal,
      });

      if (!response.ok) {
        const errorData = (await response.json().catch(() => ({
          error: 'HTTP_ERROR',
          message: response.statusText,
          statusCode: response.status,
          timestamp: new Date().toISOString(),
        }))) as ApiError;
        throw errorData;
      }

      return (await response.json()) as T;
    } finally {
      clearTimeout(timer);
    }
  }

  /**
   * Auth Service: Authenticate user credentials and retrieve bearer token
   */
  async login(payload: LoginRequest): Promise<LoginResponse> {
    const res = await this.request<LoginResponse>('/api/v1/auth/login', {
      method: 'POST',
      body: JSON.stringify(payload),
    });
    this.authToken = res.token;
    return res;
  }

  /**
   * Catalog Service: Query product inventory
   */
  async listProducts(category?: string, limit = 20): Promise<ProductItem[]> {
    const query = new URLSearchParams();
    if (category) query.set('category', category);
    query.set('limit', String(limit));
    return this.request<ProductItem[]>(\`/api/v1/catalog/products?\${query.toString()}\`, {
      method: 'GET',
    });
  }

  /**
   * Order Service: Create and dispatch new order
   */
  async createOrder(order: CreateOrderRequest): Promise<OrderRecord> {
    return this.request<OrderRecord>('/api/v1/orders', {
      method: 'POST',
      body: JSON.stringify(order),
    });
  }
}
`;
}

